#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NSKU 5

static long stock[NSKU] = {0, 0, 0, 0, 0};
static const long price[NSKU] = {10, 20, 30, 40, 50};

int main(int argc, char **argv)
{
    long revenue = 0;
    int i = 1;
    while (i + 2 < argc) {
        const char *op = argv[i];
        long sku = strtol(argv[i + 1], NULL, 10);
        long qty = strtol(argv[i + 2], NULL, 10);
        i += 3;
        if (sku < 0 || sku >= NSKU) {
            puts("INVALID_SKU");
            continue;
        }
        if (op[0] == 'S' && op[1] == '\0') {
            if (qty < 0) { puts("INVALID_OP"); continue; }
            if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            } else {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%ld qty=%ld revenue+=%ld\n", sku, qty, price[sku] * qty);
            }
        } else if (op[0] == 'R' && op[1] == '\0') {
            if (qty < 0) { puts("INVALID_OP"); continue; }
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else {
            puts("INVALID_OP");
        }
    }
    printf("FINAL stock=");
    for (int j = 0; j < NSKU; ++j) {
        if (j > 0) putchar(',');
        printf("%ld", stock[j]);
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
